local stb=0
for ttb=2,#ptb do
stb=stb+(ptb[ttb]-ptb[ttb-1]).Magnitude
end
local utb=0
for vtb=2,#ptb do
local wtb,xtb=ptb[vtb-1],ptb[vtb]
local ytb=(xtb-wtb).Magnitude
local ztb=math.max(1,math.floor(ytb/2))
for Atb=0,ztb-1 do
local Btb=wtb:Lerp(xtb,Atb/ztb)
table.insert(O.samples,{pos=Btb,prog=(utb+ytb*Atb/ztb)/math.max(1,stb),lane=ntb.Name})
